styles:
/* DR-013: one shared surface. The counterexample changes DOM order only. */
[data-rule="DR-013"] .behavior-pair {
  row-gap: 0.75rem;
}
[data-rule="DR-013"] .example {
  display: grid;
  grid-template-rows: subgrid;
  grid-row: span 2;
}
[data-rule="DR-013"] .example h3 {
  margin: 0.75rem 0 0;
  font-size: 1rem;
}
[data-rule="DR-013"] .explanation {
  display: none;
}
[data-rule="DR-013"] .sample {
  min-height: 0;
  padding: 1.5em;
  font-size: 1rem;
}
[data-rule="DR-013"] .sample[data-enlarged="true"] {
  font-size: 1.25rem;
}
[data-rule="DR-013"] .priority-heading {
  margin-bottom: 1.25em;
}
[data-rule="DR-013"] .priority-heading h4 {
  font-size: 1.25em;
  line-height: 1.3;
  margin: 0 0 0.4em;
}
[data-rule="DR-013"] .priority-heading p {
  margin: 0;
  font-size: 0.875em;
  color: light-dark(#4c6256, #b5c8bc);
}
[data-rule="DR-013"] .hierarchy {
  display: flex;
  flex-direction: column;
  gap: 1.25em;
}
[data-rule="DR-013"] [data-priority] {
  min-width: 0;
  border-top: 1px solid light-dark(#d1dbd4, #405348);
  padding-top: 1.25em;
}
[data-rule="DR-013"] h5 {
  font-size: 1.125em;
  line-height: 1.35;
  margin: 0;
}
[data-rule="DR-013"] [data-priority] p {
  margin: 0.5em 0 0;
  line-height: 1.5;
}
[data-rule="DR-013"] .volume strong {
  display: block;
  margin-top: 0.25em;
  font-size: 1.5em;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
}
[data-rule="DR-013"] button {
  margin-top: 0.875em;
  min-width: 2.75rem;
  min-height: 2.75rem;
  font-size: 0.875em;
  white-space: normal;
}
@media (max-width: 700px) {
  [data-rule="DR-013"] .sample {
    padding: 1em;
  }
}

initializer:
function configurePriority(sample, good) {
  const hierarchy = sample.querySelector(".hierarchy");
  // Only the reading order changes; styles, facts, and behavior are shared.
  if (!good) hierarchy.prepend(sample.querySelector(".volume"));
  const trigger = sample.querySelector('[data-role="respond"]');
  const result = sample.querySelector('[data-role="result"]');
  result.id = `priority-result-${good ? "good" : "bad"}`;
  trigger.setAttribute("aria-controls", result.id);
  const setOpen = (open) => {
    result.textContent = open
      ? "EP 1042, EP 1047, and EP 1051 are awaiting address corrections."
      : "";
    result.hidden = !open;
    trigger.setAttribute("aria-expanded", String(open));
    trigger.textContent = open ? "Hide exceptions" : "Review 3 exceptions";
  };
  trigger.onclick = () => setOpen(result.hidden);
  sample.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !result.hidden) {
      setOpen(false);
      trigger.focus();
    }
  });
}
